    days: [
      {date: "2026-06-15", busy: [{start: "14:30", end: "17:00"}]},
      {date: "2026-06-16", busy: []},
      {date: "2026-06-17", busy: [{start: "09:00", end: "10:00"}]},
      {date: "2026-06-18", busy: []},
      {date: "2026-06-19", busy: [{start: "16:00", end: "17:00"}]}
    ]
  },
  {
    user_id: "U4",
    days: [
      {date: "2026-06-15", busy: [{start: "10:00", end: "11:00"}]},
      {date: "2026-06-16", busy: [{start: "11:00", end: "12:00"}]},
      {date: "2026-06-17", busy: [{start: "15:30", end: "16:30"}]},
      {date: "2026-06-18", busy: []},
      {date: "2026-06-19", busy: []}
    ]
  }
]

// Convert HH:MM to minutes since midnight
to_min = fun(t) {
  parts = text.split(t, ":")
  return number.parse(parts[0]) * 60 + number.parse(parts[1])
}

// Possible start times in minutes: 9:00 to 16:00 every 30 min
starts = [540, 570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960]
// 540=09:00 ... 960=16:00

dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

// For each date, build union of busy intervals across all users
// Then find earliest start where [start, start+60) doesn't overlap any busy

// Helper: does [s, e) overlap [bs, be)?  s < be and bs < e
// We'll check slot [start, start+60]

find = fold acc = null for d_idx in list.range(0, 5) {
  skip if acc != null
  date = dates[d_idx]
  // collect all busy for this date
  all_busy = fold bacc = [] for u in users_data {
    day = u.days[d_idx]
    return bacc + day.busy
  }
  // check each start
  found = fold f = null for s in starts {
    skip if f != null
    e = s + 60
    // check overlap with any busy
    conflict = fold c = false for b in all_busy {
      skip if c
      bs = // to_min
        number.parse(text.split(b.start, ":")[0]) * 60 + number.parse(text.split(b.start, ":")[1])
      be = number.parse(text.split(b.end, ":")[0]) * 60 + number.parse(text.split(b.end, ":")[1])
      overlaps = s < be and bs < e
      return overlaps
    }
    return { start_min: s, end_min: e, date: date } if not conflict else null
  }
  return found
}

// format result
format_time = fun(mins) {
  h = number.floor(mins / 60)
  m = mins - h * 60
  hs = text.slice("0" + json.encode(h), -2, null)  // pad? 
  // simpler
  hstr = if h < 10 { return "0" + json.encode(h) } else { return json.encode(h) }
  mstr = if m < 10 { return "0" + json.encode(m) } else { return json.encode(m) }
  return hstr + ":" + mstr
}

result = if find != null {
  st = format_time(find.start_min)
  en = format_time(find.end_min)
  return {
    start: find.date + "T" + st + ":00Z",
    end: find.date + "T" + en + ":00Z",
    debug: find
  }
} else {
  return { error: "none found" }
}

return result

