starts = [540, 570, 600, 630, 660, 690, 720, 750, 780, 810, 840, 870, 900, 930, 960]
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]

// Build per-date list of busy intervals in minutes
day_busy = for d_idx in list.range(0, 5) {
  all_busy = fold bacc = [] for u in users_data {
    day = u.days[d_idx]
    converted = for b in day.busy {
      sp = text.split(b.start, ":")
      ep = text.split(b.end, ":")
      bs = number.parse(sp[0]) * 60 + number.parse(sp[1])
      be = number.parse(ep[0]) * 60 + number.parse(ep[1])
      return { bs: bs, be: be }
    }
    return bacc + converted
  }
  return { date: dates[d_idx], busy: all_busy }
}

// Find earliest slot
find = fold acc = null for day in day_busy {
  skip if acc != null
  found = fold f = null for s in starts {
    skip if f != null
    e = s + 60
    conflict = fold c = false for b in day.busy {
      skip if c
      return s < b.be and b.bs < e
    }
    return { start_min: s, end_min: e, date: day.date } if not conflict else null
  }
  return found
}

h_start = number.floor(find.start_min / 60)
m_start = find.start_min - h_start * 60
h_end = number.floor(find.end_min / 60)
m_end = find.end_min - h_end * 60

h_start_s = if h_start < 10 { return "0" + json.encode(h_start) } else { return json.encode(h_start) }
m_start_s = if m_start < 10 { return "0" + json.encode(m_start) } else { return json.encode(m_start) }
h_end_s = if h_end < 10 { return "0" + json.encode(h_end) } else { return json.encode(h_end) }
m_end_s = if m_end < 10 { return "0" + json.encode(m_end) } else { return json.encode(m_end) }

start_iso = find.date + "T" + h_start_s + ":" + m_start_s + ":00Z"
end_iso = find.date + "T" + h_end_s + ":" + m_end_s + ":00Z"

_submitted = submit_result({ answer: { start: start_iso, end: end_iso } })
return { start: start_iso, end: end_iso, recorded: _submitted.recorded }
